styles:
.w-webflow-badge{display: none!important;}
input,
textarea,
button,
select,
a {
    -webkit-tap-highlight-color: transparent;
}
* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  -webkit-appearance:none;
}
textarea { resize: none; }
:root {
  --main-dark: black;
  --main-light: white;
}
::selection {
    background: var(--main-dark);
  color: var(--main-light);
  text-shadow: none;
}
img::selection, svg::selection {
    background: transparent;
}
a {
    color: inherit;
}
body {
    text-rendering: geometricPrecision;
}
.invisible-scrollbar::-webkit-scrollbar {
  display: none;
}
.ss-anchor-link:hover .ss-anchor-name,
.ss-anchor-link.w--current .ss-anchor-name{ display: block; }
.ss-three-ksps-link:hover .ss-fig { transform: scale(1.1); }
.ss-scrollbar::-webkit-scrollbar {
  width: 5px; 
  height: 5px;
}
.ss-scrollbar::-webkit-scrollbar-thumb {
  background-color: rgba(255, 255, 255, 0); 
  border-radius: 5px; 
  transition: background-color .5s;
}
.ss-scrollbar::-webkit-scrollbar-thumb:hover {
  background-color: rgba(255, 255, 255, 0.5); 
}
.ss-scrollbar::-webkit-scrollbar-track {
  background-color: transparent; 
  border-radius: 0px; 
}
.ss-scrollbar:hover::-webkit-scrollbar-thumb {
    background-color: rgba(255, 255, 255, 0.2); 
}
.swiper.is-default {
  -webkit-mask-image: linear-gradient(to right, transparent 0%, black 20%, black 80%, transparent 100%);
  mask-image: linear-gradient(to right, transparent 0%, black 20%, black 80%, transparent 100%);
}
.ss-fake {
  -webkit-filter: url("#blur");
  filter: url("#blur");
  mask-image: linear-gradient(to left, transparent 0%, black 10%, black 100%);
}
@media screen and (min-width: 479px) { 
	.swiper-slide-active .ss-carousel-text,
	.swiper-slide-active .ss-carousel-cooling-card { opacity: 1; }
	.swiper-slide-active  .ss-carousel-overflow { width: 20rem; }
}
@media screen and (min-width: 1920px) {
  .swiper-slide-active  .ss-carousel-overflow { width: 25rem; }
}
@media screen and (max-width: 478px) { 
  .swiper-3d.is-default {
  	perspective: 5000px;
  }
}

