@-webkit-keyframes static {
    0% {
        opacity: 1
    }
    100% {
        opacity: 1
    }
}
@keyframes static {
    0% {
        opacity: 1
    }
    100% {
        opacity: 1
    }
}
@-webkit-keyframes breathing {
    0% {
        opacity: 1
    }
    70% {
        opacity: 0
    }
}
@keyframes breathing {
    0% {
        opacity: 1
    }
    70% {
        opacity: 0
    }
}
@-webkit-keyframes strobing {
    0% {
        opacity: 1
    }
    50% {
        opacity: .3
    }
}
@keyframes strobing {
    0% {
        opacity: 1
    }
    50% {
        opacity: .3
    }
}
